    globalThis.fetch = async (input: RequestInfo | URL, init?: RequestInit) => {
      llamadas.push({ url: String(input), init });
      return {
        ok: true,
        json: async () => ({
          cargado: false,
          pid: null,
          ultimasLineas: [],
          medidoEn: new Date().toISOString()
        })
      } as Response;
    };

    render(<TunelMetaGenesisEstado />);
